build() {
    mkdir -p build
    cd build
    # The tests need munit, pytest and structlog. liboeffis talks to the
    # RemoteDesktop portal over D-Bus with libsystemd's sd-bus. libxkbcommon and
    # libevdev are found when present, without an option to say so; they are
    # used by the debugging and demonstration tools. The protocol code is
    # generated by a Python script that needs jinja2.
    meson setup .. \
        --prefix=/usr \
        --libdir=lib \
        --buildtype=release \
        -D tests=disabled \
        -D libei=enabled \
        -D libeis=enabled \
        -D liboeffis=enabled \
        -D sd-bus-provider=libsystemd
    ninja
}

package() {
    cd build
    DESTDIR="$DESTDIR" ninja install
}
